//! OUI vendor lookup and multi-radio grouping. OWNER: WP-C.
//!
//! CONTRACT (frozen signatures):
//! - Both functions take the RAW address, because they run in `wifi::mapping` before the
//!   BSSID is hashed. Nothing here stores or logs a raw address.
//! - [`vendor_for`]: short vendor name from the IEEE MA-L prefix; a locally administered
//!   address (bit 0x02 of the first byte) is "Private address"; `None` when unknown.
//! - [`radio_group`]: BSSIDs with the same first 5 bytes and the same high nibble of the last
//!   byte are one physical device. The key is those 5 bytes plus `last & 0xF0`.
//! - [`group_id`]: the salted hash of that key, stored as `WifiObservation::group_id`.
//!
//! The prefix table is `oui.tsv`, generated by `scripts/update-oui.sh` from the IEEE MA-L
//! registry (sorted, one `PREFIX<TAB>name` per line). It is parsed once, on first use, into a
//! sorted array and searched by binary search.

use crate::model::{hash_identifier, Salt};
use std::sync::OnceLock;

/// Shown for locally administered (randomised or virtual) addresses, which have no vendor.
pub const PRIVATE_ADDRESS: &str = "Private address";

const OUI_TSV: &str = include_str!("oui.tsv");

/// Parse six colon-separated hex bytes (or `-` separated, any case) into bytes.
fn parse_mac(raw: &str) -> Option<[u8; 6]> {
    let mut out = [0u8; 6];
    let mut parts = raw.trim().split([':', '-']);
    for byte in out.iter_mut() {
        let p = parts.next()?;
        if p.is_empty() || p.len() > 2 {
            return None;
        }
        *byte = u8::from_str_radix(p, 16).ok()?;
    }
    parts.next().is_none().then_some(out)
}

fn table() -> &'static [(u32, &'static str)] {
    static TABLE: OnceLock<Vec<(u32, &'static str)>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut v: Vec<(u32, &'static str)> = OUI_TSV
            .lines()
            .filter_map(|l| {
                let (p, name) = l.split_once('\t')?;
                Some((u32::from_str_radix(p, 16).ok()?, name))
            })
            .collect();
        // The generator sorts; sorting again keeps a hand-edited file safe for binary search.
        v.sort_by_key(|e| e.0);
        v
    })
}

/// Vendor for a 24-bit prefix (`0xAABBCC`), straight from the registry table.
fn lookup_prefix(prefix: u32) -> Option<&'static str> {
    let t = table();
    t.binary_search_by_key(&prefix, |e| e.0)
        .ok()
        .map(|i| t[i].1)
}

/// Short vendor name for a raw MAC/BSSID, or `None` when it cannot be parsed or is unknown.
pub fn vendor_for(raw_mac: &str) -> Option<String> {
    let b = parse_mac(raw_mac)?;
    if b[0] & 0x02 != 0 {
        return Some(PRIVATE_ADDRESS.to_string());
    }
    lookup_prefix(u32::from_be_bytes([0, b[0], b[1], b[2]])).map(str::to_string)
}

/// Multi-radio group key for a raw BSSID: first 5 bytes + `last & 0xF0`. `None` when unparsable.
pub fn radio_group(raw_bssid: &str) -> Option<[u8; 6]> {
    let mut b = parse_mac(raw_bssid)?;
    b[5] &= 0xF0;
    Some(b)
}

/// Salted hash of [`radio_group`], or `None` when the BSSID is unparsable.
pub fn group_id(salt: &Salt, raw_bssid: &str) -> Option<String> {
    let k = radio_group(raw_bssid)?;
    // Namespaced so a group id can never equal a plain BSSID hash.
    let key = format!(
        "radio-group:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}",
        k[0], k[1], k[2], k[3], k[4], k[5]
    );
    Some(hash_identifier(salt, &key))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn salt(b: u8) -> Salt {
        Salt::from_bytes(vec![b; 32])
    }

    /// A globally administered address built at runtime from a prefix in the generated table,
    /// so no real-looking MAC is written into the source.
    fn mac_from_table_line(line: usize) -> (String, String) {
        let (p, name) = OUI_TSV.lines().nth(line).unwrap().split_once('\t').unwrap();
        let mac = format!("{}:{}:{}:00:00:01", &p[0..2], &p[2..4], &p[4..6]);
        (mac, name.to_string())
    }

    #[test]
    fn table_is_sorted_unique_and_sized() {
        let t = table();
        assert!(t.len() > 30_000, "table has {} entries", t.len());
        assert!(t.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(t.iter().all(|e| !e.1.is_empty() && !e.1.contains('\t')));
    }

    #[test]
    fn known_prefixes_resolve_to_their_table_vendor() {
        let n = table().len();
        // Spread across the table, none hand-picked. A locally administered prefix in the
        // registry is skipped (those always read "Private address").
        let mut checked = 0;
        for line in [0, n / 7, n / 3, n / 2, n - 1] {
            let (mac, name) = mac_from_table_line(line);
            let first = u8::from_str_radix(&mac[0..2], 16).unwrap();
            if first & 0x02 != 0 {
                continue;
            }
            assert_eq!(vendor_for(&mac), Some(name), "line {line}");
            checked += 1;
        }
        assert!(checked >= 3, "only {checked} lookups ran");
    }

    #[test]
    fn lookup_is_case_and_separator_insensitive() {
        let (mac, name) = mac_from_table_line(1000);
        if u8::from_str_radix(&mac[0..2], 16).unwrap() & 0x02 != 0 {
            return; // covered by the LAA test
        }
        assert_eq!(vendor_for(&mac.to_uppercase()), Some(name.clone()));
        assert_eq!(vendor_for(&mac.replace(':', "-")), Some(name));
    }

    #[test]
    fn locally_administered_is_private_address() {
        // Every first byte with the 0x02 bit set, built at runtime to keep MAC-shaped text
        // out of the source.
        let mut checked = 0;
        for first in (0u8..=255).filter(|b| b & 0x02 != 0) {
            let m = format!("{first:02x}:11:22:33:44:55");
            assert_eq!(vendor_for(&m).as_deref(), Some("Private address"), "{m}");
            checked += 1;
        }
        assert_eq!(checked, 128);
        assert_eq!(
            vendor_for("02:00:00:00:00:01").as_deref(),
            Some("Private address")
        );
    }

    #[test]
    fn unknown_prefix_and_garbage_give_none() {
        // Unassigned in MA-L: global bit clear, absent from the table.
        let absent = (0u32..0x0100_0000)
            .find(|p| (p >> 16) & 0x03 == 0 && lookup_prefix(*p).is_none())
            .unwrap();
        let mac = format!(
            "{:02x}:{:02x}:{:02x}:00:00:01",
            absent >> 16,
            (absent >> 8) & 0xff,
            absent & 0xff
        );
        assert_eq!(vendor_for(&mac), None);
        for bad in [
            "",
            "not a mac",
            "02:00:00:00:00",
            "02:00:00:00:00:00:01",
            "zz:00:00:00:00:00",
        ] {
            assert_eq!(vendor_for(bad), None, "{bad:?}");
            assert_eq!(radio_group(bad), None, "{bad:?}");
            assert_eq!(group_id(&salt(1), bad), None, "{bad:?}");
        }
    }

    #[test]
    fn radio_group_merges_the_same_high_nibble() {
        let g = |m: &str| radio_group(m).unwrap();
        let base = g("02:00:00:aa:bb:00");
        assert_eq!(base, [0x02, 0, 0, 0xaa, 0xbb, 0x00]);
        for m in [
            "02:00:00:aa:bb:04",
            "02:00:00:aa:bb:08",
            "02:00:00:aa:bb:0c",
            "02:00:00:AA:BB:0F",
        ] {
            assert_eq!(g(m), base, "{m}");
        }
    }

    #[test]
    fn radio_group_separates_different_devices() {
        let base = radio_group("02:00:00:aa:bb:04");
        // Different high nibble of the last byte, different 5th byte, different earlier byte.
        for m in [
            "02:00:00:aa:bb:14",
            "02:00:00:aa:bc:04",
            "02:00:00:ab:bb:04",
            "02:00:01:aa:bb:04",
        ] {
            assert_ne!(radio_group(m), base, "{m}");
        }
    }

    #[test]
    fn group_id_is_salted_stable_and_distinct_from_the_bssid_hash() {
        let a = group_id(&salt(1), "02:00:00:aa:bb:04").unwrap();
        assert_eq!(a.len(), 64);
        assert_eq!(a, group_id(&salt(1), "02:00:00:AA:BB:0C").unwrap());
        assert_ne!(a, group_id(&salt(1), "02:00:00:aa:bb:14").unwrap());
        assert_ne!(a, group_id(&salt(2), "02:00:00:aa:bb:04").unwrap());
        assert_ne!(a, hash_identifier(&salt(1), "02:00:00:aa:bb:00"));
        assert!(!a.contains("aabb"));
    }
}
